<?php
 namespace QQWorld\Payment\Test\Unit\Gateway\Validator; class CountryValidatorTest extends \PHPUnit\Framework\TestCase { protected $model; protected $configMock; protected $resultFactoryMock; protected $resultMock; protected function setUp() { $this->configMock = $this->getMockBuilder(\QQWorld\Payment\Gateway\ConfigInterface::class) ->getMockForAbstractClass(); $this->resultFactoryMock = $this->getMockBuilder( \QQWorld\Payment\Gateway\Validator\ResultInterfaceFactory::class )->setMethods(['create']) ->disableOriginalConstructor() ->getMock(); $this->resultMock = $this->getMockBuilder(\QQWorld\Payment\Gateway\Validator\Result::class) ->disableOriginalConstructor() ->getMock(); $this->model = new \QQWorld\Payment\Gateway\Validator\CountryValidator( $this->resultFactoryMock, $this->configMock ); } public function testValidateAllowspecificTrue($storeId, $country, $allowspecific, $specificcountry, $isValid) { $validationSubject = ['storeId' => $storeId, 'country' => $country]; $this->configMock->expects($this->at(0)) ->method('getValue') ->with('allowspecific', $storeId) ->willReturn($allowspecific); $this->configMock->expects($this->at(1)) ->method('getValue') ->with('specificcountry', $storeId) ->willReturn($specificcountry); $this->resultFactoryMock->expects($this->once()) ->method('create') ->with(['isValid' => $isValid, 'failsDescription' => []]) ->willReturn($this->resultMock); $this->assertSame($this->resultMock, $this->model->validate($validationSubject)); } public function validateAllowspecificTrueDataProvider() { return [ [1, 'US', 1, 'US,UK,CA', true], [1, 'BJ', 1, 'US,UK,CA', false] ]; } public function testValidateAllowspecificFalse($storeId, $allowspecific, $isValid) { $validationSubject = ['storeId' => $storeId]; $this->configMock->expects($this->at(0)) ->method('getValue') ->with('allowspecific', $storeId) ->willReturn($allowspecific); $this->resultFactoryMock->expects($this->once()) ->method('create') ->with(['isValid' => $isValid, 'failsDescription' => []]) ->willReturn($this->resultMock); $this->assertSame($this->resultMock, $this->model->validate($validationSubject)); } public function validateAllowspecificFalseDataProvider() { return [ [1, 0, true] ]; } } 